-- ─────────────────────────────────────────────────────────────────────────────
-- Каталог курса «Бухгалтерия: Excel, 1С и закон на практике» (acc-ru).
-- СГЕНЕРИРОВАНО scripts/accounting/build_docs.mjs — не править руками.
--
-- НЕ ПРИМЕНЯЕТСЯ АВТОМАТИЧЕСКИ И НЕ ЛЕЖИТ В supabase/migrations: заводить курс в
-- рабочую базу можно только после согласования Дани. Курс создаётся в статусе
-- draft (ученики его не видят), владелец — как у AP-химии и биологии.
--
-- Идемпотентно: повторный прогон ничего не создаёт заново и не трогает уже
-- существующие строки (в т. ч. lessons.content, отредактированный учителем).
-- Нумерация уроков с НУЛЯ: short_id = 'acc-ru-<lesson_number>'.
-- Конспекты и домашки лежат в коде (src/data/accounting) и подставляются, пока
-- lessons.content пуст. Файлы уроков — в public/courses/accounting (раздаются
-- самим приложением); для мобильных сборок проверить доступность пути.
-- Откат: delete from lessons where short_id like 'acc-ru-%';
--        delete from course_modules where course_id = (select id from courses where short_id = 'acc-ru');
--        delete from courses where short_id = 'acc-ru';
-- ─────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_course_id uuid;
  v_owner uuid;
  v_mod uuid[] := array[]::uuid[];
  r record;
  v_id uuid;
begin
  select created_by into v_owner from courses where short_id = 'apchem-ru' limit 1;

  insert into courses (short_id, kind, title, subject, level, description, status, color, bg, created_by)
  values ('acc-ru', 'course', 'Бухгалтерия: Excel, 1С и закон на практике', 'Бухгалтерия', 'Практикующий бухгалтер',
    'Практический курс для бухгалтера, который ведёт несколько организаций: Excel и Power Query, сверки, 1С, самозанятые, зарплата и численность, налоги, закрытие месяца, ИИ, безопасность и переход на ФСБУ 2027. 335 уроков, справочник по рабочим вопросам, учебные файлы.',
    'draft', '#2E6FD8', '#E3EDFB', v_owner)
  on conflict (short_id) do nothing;

  select id into v_course_id from courses where short_id = 'acc-ru';

  for r in
    select * from (values
      ('Введение', 0),
      ('1. Организация рабочего пространства', 1),
      ('2. Excel с самых основ', 2),
      ('3. Очистка и обработка Excel', 3),
      ('4. Формулы Excel для бухгалтера', 4),
      ('5. Сверки', 5),
      ('6. Отчётность и аналитика', 6),
      ('7. Power Query и автоматизация Excel', 7),
      ('8. Google Таблицы', 8),
      ('9. Основы российского бухучёта', 9),
      ('10. 1С — повседневная работа', 10),
      ('11. Первичные документы и хозяйственные операции', 11),
      ('12. Банк и расчёты', 12),
      ('13. Самозанятые — подробный практикум', 13),
      ('14. Зарплата и кадры', 14),
      ('15. Налоги и отчётность РФ', 15),
      ('16. Закрытие месяца и контроль', 16),
      ('21. Переход на 2027 год — ФСБУ и иные изменения', 17),
      ('17. Искусственный интеллект', 18),
      ('18. Продвинутая автоматизация', 19),
      ('19. Информационная безопасность', 20),
      ('20. Итоговые проекты', 21),
      ('Дополнительно. ИИ: основы, техники и мировая практика', 22),
      ('22. Совместимость версий Excel: базовый маршрут и современные возможности', 23),
      ('Дополнительно. Power Query по шагам и язык M', 24),
      ('Дополнительно. Проект: автоматизация численности за 10 минут', 25),
      ('Дополнительно. Формулы для вашей работы: рецепты под задачи группы компаний', 26),
      ('Дополнительно. Энциклопедия функций: ссылки, операторы, числа и логика', 27),
      ('Дополнительно. Энциклопедия функций: поиск, массивы и современный Excel', 28),
      ('Дополнительно. Энциклопедия функций: текст, даты и финансы', 29),
      ('23. Управленческий учет группы строительных и производственных компаний', 30),
      ('24. Производственные калькуляции, стройка и транспорт', 31),
      ('25. Документы в один клик: коммерческие предложения и ответы ведомствам', 32),
      ('26. Сквозные отраслевые проекты и внедрение', 33)
    ) as t(label, pos) order by pos
  loop
    select id into v_id from course_modules where course_id = v_course_id and label = r.label limit 1;
    if v_id is null then
      insert into course_modules (course_id, label, position) values (v_course_id, r.label, r.pos) returning id into v_id;
    end if;
    v_mod := v_mod || v_id;
  end loop;

  insert into lessons (course_id, module_id, short_id, title, lesson_number, position, kind, shape, materials)
  select v_course_id, v_mod[d.block], 'acc-ru-' || d.n, d.title, d.n, d.n, 'lesson',
         case when d.n in (0, 334) then 'diamond' else 'circle' end, d.materials::jsonb
  from (values
    (0, 1, 'Знакомство: расскажите о своей работе', '{}'),
    (1, 1, 'Как устроен курс и как им пользоваться на работе', '{"materials":[{"id":"acc-praktikum-ishodnyj.xlsx","name":"praktikum-ishodnyj.xlsx","path":"/courses/accounting/praktikum-ishodnyj.xlsx","url":"/courses/accounting/praktikum-ishodnyj.xlsx","size":14769,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},{"id":"acc-chislennost-shablon.xlsx","name":"chislennost-shablon.xlsx","path":"/courses/accounting/chislennost-shablon.xlsx","url":"/courses/accounting/chislennost-shablon.xlsx","size":3193507,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},{"id":"acc-sverka-shablon.xlsx","name":"sverka-shablon.xlsx","path":"/courses/accounting/sverka-shablon.xlsx","url":"/courses/accounting/sverka-shablon.xlsx","size":14832,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},{"id":"acc-samozanyatye-kontrol.xlsx","name":"samozanyatye-kontrol.xlsx","path":"/courses/accounting/samozanyatye-kontrol.xlsx","url":"/courses/accounting/samozanyatye-kontrol.xlsx","size":22546,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},{"id":"acc-vygruzki-dlya-power-query.zip","name":"vygruzki-dlya-power-query.zip","path":"/courses/accounting/vygruzki-dlya-power-query.zip","url":"/courses/accounting/vygruzki-dlya-power-query.zip","size":27173,"mime":"application/zip"}]}'),
    (2, 1, 'Справочник: найти урок по рабочему вопросу', '{}'),
    (3, 2, 'Папки и документы: одна схема для всех организаций', '{}'),
    (4, 2, 'Правила именования файлов', '{}'),
    (5, 2, 'Месячные отчёты: пакет документов за месяц', '{"materials":[{"id":"acc-zakrytie-mesyaca-cheklist.xlsx","name":"zakrytie-mesyaca-cheklist.xlsx","path":"/courses/accounting/zakrytie-mesyaca-cheklist.xlsx","url":"/courses/accounting/zakrytie-mesyaca-cheklist.xlsx","size":10840,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}]}'),
