    (11, 2, 'Пакетное переименование файлов', '{"materials":[{"id":"acc-uchebnye-fajly-windows.zip","name":"uchebnye-fajly-windows.zip","path":"/courses/accounting/uchebnye-fajly-windows.zip","url":"/courses/accounting/uchebnye-fajly-windows.zip","size":23671,"mime":"application/zip"}]}'),
    (12, 2, 'PDF и архивы: как сохранить и отправить', '{}'),
    (13, 3, 'Откройте копию, а не оригинал: интерфейс, ячейки, строки, столбцы, диапазоны', '{"materials":[{"id":"acc-praktikum-ishodnyj.xlsx","name":"praktikum-ishodnyj.xlsx","path":"/courses/accounting/praktikum-ishodnyj.xlsx","url":"/courses/accounting/praktikum-ishodnyj.xlsx","size":14769,"mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}]}'),
